[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$ProjectPath)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest;$ProjectPath=[IO.Path]::GetFullPath($ProjectPath);$utf8=New-Object Text.UTF8Encoding($false,$true)
function Get-LowerHash([string]$p){(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant()}
function W([string]$p,[object]$v){if(Test-Path $p){throw "Create-new evidence target exists: $p"};$s=($v|ConvertTo-Json -Depth 20).Replace("`r`n","`n").Replace("`r","`n")+"`n";$t=$p+'.tmp.'+[Guid]::NewGuid().ToString('N');[IO.File]::WriteAllText($t,$s,$utf8);[IO.File]::Move($t,$p)}
