$m=Join-Path $ProjectPath 'Research\Gate13R_36h_10pct_4Lane_Attempt9_Derivation_Partial_Manifest.v1.json';$f=Join-Path $ProjectPath 'Research\Gate13R_36h_10pct_4Lane_Attempt9_Derivation_Failure.v1.json';$c=Join-Path $ProjectPath 'Research\Gate13R_36h_10pct_4Lane_Attempt9_Derivation_Checkpoint.v1.json';$roots=[ordered]@{verification=Test-Path (Join-Path $ProjectPath 'Research\Verification\Gate13R_36h_10pct_4Lane\v9');pilot=Test-Path (Join-Path $ProjectPath 'Research\PilotRuns\Gate13R_36h_10pct_4Lane\v9');clone=Test-Path 'H:\DDM_Final_Project_Gate13R36H\v9';formal=Test-Path (Join-Path $ProjectPath 'Research\FormalRuns\Gate13R_36h_10pct_4Lane\v1')}
$mv=[ordered]@{schemaVersion=1;manifestKind='gate13r-36h-attempt9-derivation-partial-manifest-v1';createdAtUtc=[DateTime]::UtcNow.ToString('o');status='FAILED-PRE-WRITE';files=$files;roots=$roots;unityProcessCount=@(Get-Process Unity -ErrorAction SilentlyContinue).Count;pilotStarted=$false;formalCampaign=$false;passed=$false};W $m $mv
$fv=[ordered]@{schemaVersion=1;receiptKind='gate13r-36h-attempt9-derivation-failure-v1';createdAtUtc=[DateTime]::UtcNow.ToString('o');status='FAILED-PRE-WRITE';phase='frozen-evidence-resolution';errorMessage='The generic v8-to-v9 route changed historical attempt-4 static evidence from PreImplementation/v8/StaticUnitV4 to nonexistent v9.';allowedRepair='A new versioned attempt must pin attempt-2 static evidence to v7, attempt-4 static evidence to v8, and lock-hygiene unit evidence to v9.';partialManifestSha256=Get-LowerHash $m;roots=$roots;unityProcessCount=$mv.unityProcessCount;pilotStarted=$false;formalCampaign=$false;passed=$false};W $f $fv
$cv=[ordered]@{schemaVersion=1;checkpointKind='gate13r-36h-attempt9-derivation-checkpoint-v1';createdAtUtc=[DateTime]::UtcNow.ToString('o');status='failed-no-resume';attempt=9;failedPhase='frozen-evidence-resolution';failureReceiptSha256=Get-LowerHash $f;partialManifestSha256=Get-LowerHash $m;nextAllowedAction='Create a new versioned attempt with all historical preimplementation directories explicitly pinned.';pilotStarted=$false;formalCampaign=$false;passed=$false};W $c $cv
